// La pose de reposo tiene que ser idéntica al dibujo base (lo comprueba `pxcli anim check`).
rest(() => {
  draw("base");
});

// Corazón magenta redibujado por encima de la base. nivel 1: se aclara; nivel 2: crece 1 px y casi blanco.
part("corazon", ({ nivel }) => {
  const dist = (x, y) => Math.hypot(x + 0.5 - 32, y + 0.5 - 32);
  if (nivel >= 2) {
    for (let y = 24; y <= 39; y++) {
      for (let x = 24; x <= 39; x++) {
        const d = dist(x, y);
        if (d > 7.1) continue;
        if (d > 6.1) set_pixel(x, y, x + y > 63 ? "#b41a82" : "#c0168a");
        else if (d > 4.2) set_pixel(x, y, "#ff2fa8");
        else if (d > 2.9) set_pixel(x, y, "#ff63be");
        else if (d > 1.8) set_pixel(x, y, "#ffaadb");
        else if (d > 0.8) set_pixel(x, y, "#ffcfeb");
        else set_pixel(x, y, "#ffffff");
      }
    }
  } else if (nivel >= 1) {
    for (let y = 28; y <= 35; y++) {
      for (let x = 28; x <= 35; x++) {
        const d = dist(x, y);
        if (d > 3.3) continue;
        set_pixel(x, y, d > 2.1 ? "#ff63be" : d > 0.8 ? "#ff97d4" : "#ffcfeb");
      }
    }
  }
  // brillo especular de arriba a la izquierda
  if (nivel >= 1) {
    fill_rect(29, 28, 2, 2, "#ffffff");
    set_pixel(28, 29, "#ffcae9");
  }
});

// Caras iluminadas de los cristales: nivel 1 un poco más claras, nivel 2 brillan.
part("brillo_cristales", ({ nivel }) => {
  if (nivel < 1) return;
  const cian = nivel >= 2 ? "#90eeff" : "#5ae6ff";
  const violeta = nivel >= 2 ? "#dec7ff" : "#d3b3ff";
  // cristal cian de arriba
  [[31, 5], [31, 6], [30, 7], [29, 9], [28, 10], [29, 10], [28, 11], [28, 12], [27, 13], [27, 14],
   [26, 15], [26, 16], [27, 16], [26, 17], [27, 17], [27, 18], [27, 19], [28, 18], [28, 19]]
    .forEach(([x, y]) => set_pixel(x, y, cian));
  // cristales cian de abajo (izquierdo y su espejo)
  [[14, 35], [15, 35], [16, 35], [17, 34], [18, 34], [19, 34], [17, 35], [18, 35], [19, 35],
   [13, 37], [14, 37], [12, 38], [13, 38], [12, 39], [11, 40], [11, 41], [10, 42]]
    .forEach(([x, y]) => { set_pixel(x, y, cian); set_pixel(63 - x, y, cian); });
  // cristales violeta de los lados (izquierdo y su espejo)
  [[12, 19], [13, 19], [14, 19], [15, 19], [16, 19], [17, 19], [18, 19], [19, 19], [20, 19], [21, 19],
   [22, 20], [22, 21], [23, 21], [23, 22]]
    .forEach(([x, y]) => { set_pixel(x, y, violeta); set_pixel(63 - x, y, violeta); });
  // cristal violeta de abajo
  [[27, 44], [28, 44], [26, 45], [27, 45], [26, 46], [27, 46], [26, 47], [26, 48], [27, 49], [28, 51]]
    .forEach(([x, y]) => set_pixel(x, y, violeta));
});

// Una función por acción: dibuja el frame f desde cero. t va de 0 a 1.
// Latido: reposo, se aclara, pico (crece 1 px), se aclara, reposo, reposo.
action("latido", { frames: 6, fps: 8, loop: true }, (f, { t }) => {
  const nivel = cycle([0, 1, 2, 1, 0, 0], f);
  draw("base");
  draw("brillo_cristales", { nivel });
  draw("corazon", { nivel });
});

